-- SOURCE-FRESH: SCM_MGR 화면 DMF0014 객체·META (DB=ZIOUI1 SERVER_HOST=localhost) FETCHED=2026-11-22 13:50:09
/* 00_PRECHECK_CLOUD — 읽기 전용(변경 없음). 결과를 보고 진행
 * 패키지 DMF0014_CLOUD_DB_MOD_20261122_1350 · 생성 tools/CloudPkg/cloud_pkg.py 1.4.1 · 2026-11-22 13:50
 * 실행 계정 = SCM_MGR (전체 F5 · 반복 실행 안전)
 */
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED

/* 1) 화면 소유 객체 — 클라우드 현재 상태 (CLOUD_STATUS 빈칸 = 클라우드에 없음 → 이 패키지가 생성) */
SELECT E.N AS OBJECT_NAME, E.T AS OBJECT_TYPE, O.STATUS AS CLOUD_STATUS, TO_CHAR(O.LAST_DDL_TIME, 'YYYY-MM-DD HH24:MI') AS CLOUD_LAST_DDL
  FROM (SELECT 'GT_DMF0014_PARAM_TOKEN' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0014' N, 'PACKAGE' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0014' N, 'PACKAGE BODY' T FROM DUAL) E
  LEFT JOIN USER_OBJECTS O ON O.OBJECT_NAME = E.N AND O.OBJECT_TYPE = E.T
 ORDER BY 1, 2;

/* 2) 공용 참조 객체(이 패키지가 만들지 않음) — 0건이어야 정상. 행 = 클라우드에 없거나 INVALID → 먼저 이관 필요 */
SELECT E.O AS OWNER, E.N AS OBJECT_NAME, E.T AS OBJECT_TYPE, NVL(MAX(A.STATUS), '없음') AS CLOUD_STATUS
  FROM (SELECT 'SCM_MGR' O, 'FN_NEXT_DAY' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'FN_SCM_GET_WHERE_SQL' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_PLN_MKT_FCST_MAKE_CUST_FCST' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_SYS_LOG_BATCH' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_SCM_SYS_LOG_BATCH' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_MST_ITEM_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SEQ1_DM_PLN_CUSTOMER_PSI_H' N, 'SEQUENCE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'STRING_SPLIT' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'FN_GET_DEPT_LIST' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PKG_SCM_USER_MNU' N, 'PACKAGE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_CUST_ITEM_MAPPING' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_DNM_EDI_CALLOFF' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_DNM_EDI_CALLOFF_MKT_FCST' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_PLN_CUST_FCST_TO_MKT_FCST' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_PLN_CUST_FCST_TO_MKT_FCST_40' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_PLN_CUST_FCST_TO_MKT_FCST_SM' N, 'PROCEDURE' T FROM DUAL) E
  LEFT JOIN ALL_OBJECTS A ON A.OWNER = E.O AND A.OBJECT_NAME = E.N AND A.OBJECT_TYPE IN (E.T, E.T || ' BODY')
 GROUP BY E.O, E.N, E.T
HAVING NVL(MAX(A.STATUS), '없음') <> 'VALID' OR MIN(A.STATUS) <> 'VALID'
 ORDER BY 1, 2;

/* 3) 참조 테이블·뷰 컬럼 누락 — 0건이어야 정상. 행 = 클라우드 표에 그 컬럼 없음 → PKG 컴파일 ORA-00904 원인.
 *    데이터·PK·배치 영향이 있어 자동 변경 안 함 — 결과를 그대로 전달(예: 2026-10-30 QA SCP_RPT_GLOBAL_PSI_MD_WW.PLAN_TYPE) */
